using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using System.Diagnostics;
using System.Text.Json.Nodes;
namespace GpuPro.Windows;
public sealed partial class MainWindow {
 async Task BuildTuning(StackPanel host){try{var id=ActiveGpu.Id;var start=new ProcessStartInfo(Path.Combine(AppContext.BaseDirectory,"gpu-tuning-worker.exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};start.ArgumentList.Add("--id");start.ArgumentList.Add(id);using var p=Process.Start(start)??throw new IOException("Consulta de controles não iniciou.");var json=p.StandardOutput.ReadToEndAsync();await p.WaitForExitAsync();var controls=JsonNode.Parse(await json)?.AsObject()??throw new IOException("Controles não disponíveis.");host.Children.Add(Text("Ajustes manuais somente nas faixas reconhecidas pelo driver. A aplicação solicita autorização do Windows e pode causar instabilidade. Nada é aplicado ao abrir a página."));if(controls.Count==0)host.Children.Add(Text("O driver não expôs controles de escrita reconhecidos para esta GPU neste Windows."));foreach(var control in controls){string domain=control.Key;var c=control.Value!.AsObject();var value=new NumberBox{Minimum=c["min"]!.GetValue<int>(),Maximum=c["max"]!.GetValue<int>(),Value=c["current"]!.GetValue<int>(),SmallChange=1,Width=160};var slider=new Slider{Minimum=value.Minimum,Maximum=value.Maximum,Value=value.Value};slider.ValueChanged+=(s,e)=>value.Value=Math.Round(slider.Value);value.ValueChanged+=(s,e)=>slider.Value=value.Value;var apply=Button("Aplicar",async()=>await ApplyTuning(id,domain,(int)value.Value));var elements=new List<UIElement>{slider,value,apply};if(domain.StartsWith("fan"))elements.Add(Button("Restaurar automático",async()=>await ApplyTuning(id,domain,-1)));host.Children.Add(Section(domain switch{"core"=>"Offset GPU · MHz","mem"=>"Offset memória · MHz","power"=>"Power limit · W",_=>"Ventoinha "+domain[3..]+" · %"},elements.ToArray()));}host.Children.Add(Text("Undervolt/tensão absoluta só aparece quando houver uma API Windows reconhecida; nenhum valor é inferido."));}catch(Exception e){host.Children.Add(Text(e.Message));Record("Overclock: "+e.Message,true);}}
 async Task ApplyTuning(string id,string domain,int value){try{if(worker!=null||benchmark)throw new InvalidOperationException("Encerre o teste antes de ajustar a GPU.");if(id!=ActiveGpu.Id)throw new InvalidOperationException("A GPU selecionada mudou. Reabra a página.");var confirm=new ContentDialog{XamlRoot=Root.XamlRoot,Title="Confirmar ajuste manual",Content=$"GPU: {ActiveGpu.Name}\nControle: {domain}\nValor: {value}\nO ajuste pode causar instabilidade. Continuar?",PrimaryButtonText="Aplicar",CloseButtonText="Cancelar",DefaultButton=ContentDialogButton.Close};if(await confirm.ShowAsync()!=ContentDialogResult.Primary)return;gpuChoice.IsEnabled=false;var executable=Path.Combine(AppContext.BaseDirectory,"gpu-tuning-worker.exe");var args=$"--apply --id {id} --domain {domain} --value {value}";using var process=Process.Start(new ProcessStartInfo(executable,args){UseShellExecute=true,Verb="runas",WorkingDirectory=AppContext.BaseDirectory})??throw new IOException("Auxiliar não iniciou.");await process.WaitForExitAsync();Record(process.ExitCode==0?$"Ajuste {domain}={value} confirmado pelo driver · {ActiveGpu.Name}":$"Ajuste {domain}={value} não confirmado. Código: {process.ExitCode}",process.ExitCode!=0);await Poll();}catch(Exception e){TestError(e);}finally{gpuChoice.IsEnabled=true;}}
}
